  from v, public.subtopics st
  join public.topics t on t.id = st.topic_id
  join public.subjects s on s.id = t.subject_id
  where s.name = 'English Literature' and t.name = 'Macbeth: Plot, Character & Context' and st.name = 'Macbeth and Lady Macbeth as characters'
    and not exists (select 1 from public.fm_exam_questions e where e.question_text = v.qt)
  returning id
)
insert into public.fm_mark_schemes (question_id, marking_style, scheme, ao_marks, spag_marks)
select id, 'levels', '{"levels":[{"level":6,"marks":[26,30],"descriptor":"Convincing, critical and exploratory. A sustained, well-structured argument; quotations chosen precisely and woven in; perceptive analysis of the writer''s methods and their effects, with subject terminology used judiciously; context explored and linked convincingly to the writer''s ideas."},{"level":5,"marks":[21,25],"descriptor":"Thoughtful and developed. A considered, coherent response; well-chosen references; examination of the writer''s methods and effects with apt terminology; thoughtful links between context and the text."},{"level":4,"marks":[16,20],"descriptor":"Clear and explained. A clear response to task and text; effective use of references; clear explanation of the writer''s methods and their effects with relevant terminology; clear understanding of context linked to the text."},{"level":3,"marks":[11,15],"descriptor":"Some explanation. Some explained response; references used to support points; some identification and explanation of methods; some awareness of context."},{"level":2,"marks":[6,10],"descriptor":"Supported and relevant comments. Relevant comments backed by some reference; awareness of the writer making choices; some awareness of context."},{"level":1,"marks":[1,5],"descriptor":"Simple, explicit comments. Simple comments with little reference to the text; little awareness of methods or context."}],"indicative":["Her invocation of spirits (''Come, you spirits'') links her to the supernatural and to the witches","''Unsex me here'': she rejects the expectations of femininity to gain the cruelty she thinks power needs","Imagery of blood, poison (''milk for gall'') and darkness presents her ambition as unnatural","Imperatives and exclamations show her control and determination","Elsewhere she dominates Macbeth: questioning his masculinity in Act 1 Scene 7, planning the murder, taking charge after it","Her power fades: excluded from Macbeth''s later plans, then the sleepwalking scene (Act 5 Scene 1) and her death","Jacobean context: the Great Chain of Being, beliefs about witchcraft and the supernatural (James I), expectations of women as obedient wives","Power that defies the natural order is shown to be destructive and short-lived"],"spag":"AO4 (4 marks), separate from the 30: 4 = consistently accurate spelling and punctuation and a wide range of vocabulary and sentence structures; 2-3 = considerable accuracy and a good range; 1 = reasonable accuracy and a reasonable range with errors that don''t hinder meaning; 0 = errors hinder meaning or the answer is not relevant."}'::jsonb, '{"AO1":12,"AO2":12,"AO3":6,"AO4":4}'::jsonb, 4 from q;

with v(qt) as (select 'Read the following extract from Stave 1 of A Christmas Carol, in which Scrooge is introduced.

Oh! But he was a tight-fisted hand at the grindstone, Scrooge! a squeezing, wrenching, grasping, scraping, clutching, covetous, old sinner! Hard and sharp as flint, from which no steel had ever struck out generous fire; secret, and self-contained, and solitary as an oyster. The cold within him froze his old features, nipped his pointed nose, shrivelled his cheek, stiffened his gait; made his eyes red, his thin lips blue; and spoke out shrewdly in his grating voice. A frosty rime was on his head, and on his eyebrows, and his wiry chin. He carried his own low temperature always about with him; he iced his office in the dog-days; and didn''t thaw it one degree at Christmas.

Starting with this extract, explore how Dickens presents Scrooge as an outsider in society.

Write about:
• how Dickens presents Scrooge in this extract
• how Dickens presents Scrooge as an outsider in the novel as a whole.

