insert into public.fm_mark_schemes (question_id, marking_style, scheme, ao_marks, spag_marks)
select id, 'levels', '{"levels":[{"level":6,"marks":[26,30],"descriptor":"Convincing, critical and exploratory. A sustained, well-structured argument; quotations chosen precisely and woven in; perceptive analysis of the writer''s methods and their effects, with subject terminology used judiciously; context explored and linked convincingly to the writer''s ideas."},{"level":5,"marks":[21,25],"descriptor":"Thoughtful and developed. A considered, coherent response; well-chosen references; examination of the writer''s methods and effects with apt terminology; thoughtful links between context and the text."},{"level":4,"marks":[16,20],"descriptor":"Clear and explained. A clear response to task and text; effective use of references; clear explanation of the writer''s methods and their effects with relevant terminology; clear understanding of context linked to the text."},{"level":3,"marks":[11,15],"descriptor":"Some explanation. Some explained response; references used to support points; some identification and explanation of methods; some awareness of context."},{"level":2,"marks":[6,10],"descriptor":"Supported and relevant comments. Relevant comments backed by some reference; awareness of the writer making choices; some awareness of context."},{"level":1,"marks":[1,5],"descriptor":"Simple, explicit comments. Simple comments with little reference to the text; little awareness of methods or context."}],"indicative":["The Inspector''s interruption of Birling''s speech about every man looking after himself","He controls the pace and structure of the play: one line of enquiry at a time, the photograph","His language is direct, blunt and morally charged; stage directions about ''massiveness, solidity and purposefulness''","The final speech: ''We are members of one body'', ''fire and blood and anguish''","His name (Goole / ghoul) and mysterious status; possibly a supernatural or symbolic figure","He acts as Priestley''s mouthpiece for socialist ideas","Contrast between the younger generation (Sheila, Eric) who learn and the older (Mr and Mrs Birling) who don''t","Context: set in 1912, written in 1945; dramatic irony about the Titanic and war; post-war hope for a welfare state"],"spag":"AO4 (4 marks), separate from the 30: 4 = consistently accurate spelling and punctuation and a wide range of vocabulary and sentence structures; 2-3 = considerable accuracy and a good range; 1 = reasonable accuracy and a reasonable range with errors that don''t hinder meaning; 0 = errors hinder meaning or the answer is not relevant."}'::jsonb, '{"AO1":12,"AO2":12,"AO3":6,"AO4":4}'::jsonb, 4 from q;

with v(qt) as (select 'Ozymandias, by Percy Bysshe Shelley

I met a traveller from an antique land,
Who said—"Two vast and trunkless legs of stone
Stand in the desert. . . . Near them, on the sand,
Half sunk a shattered visage lies, whose frown,
And wrinkled lip, and sneer of cold command,
Tell that its sculptor well those passions read
Which yet survive, stamped on these lifeless things,
The hand that mocked them, and the heart that fed;
And on the pedestal, these words appear:
My name is Ozymandias, King of Kings;
Look on my Works, ye Mighty, and despair!
Nothing beside remains. Round the decay
Of that colossal Wreck, boundless and bare
The lone and level sands stretch far away."

Compare how poets present the effects of power in ''Ozymandias'' and in one other poem from ''Power and conflict''.

[30 marks]'::text),
q as (
  insert into public.fm_exam_questions (subtopic_id, topic_id, question_text, command_word, total_marks, difficulty, exam_board, spec_ref, active)
  select st.id, t.id, v.qt, 'compare', 30, 'higher', 'AQA', '3.2.2', true
  from v, public.subtopics st
  join public.topics t on t.id = st.topic_id
  join public.subjects s on s.id = t.subject_id
  where s.name = 'English Literature' and t.name = 'Power and Conflict Poetry: Comparing Poems & Techniques' and st.name = 'Comparing presentations of power'
    and not exists (select 1 from public.fm_exam_questions e where e.question_text = v.qt)
  returning id
)
insert into public.fm_mark_schemes (question_id, marking_style, scheme, ao_marks, spag_marks)
select id, 'levels', '{"levels":[{"level":6,"marks":[26,30],"descriptor":"Convincing, critical and exploratory. A sustained, well-structured argument; quotations chosen precisely and woven in; perceptive analysis of the writer''s methods and their effects, with subject terminology used judiciously; context explored and linked convincingly to the writer''s ideas."},{"level":5,"marks":[21,25],"descriptor":"Thoughtful and developed. A considered, coherent response; well-chosen references; examination of the writer''s methods and effects with apt terminology; thoughtful links between context and the text."},{"level":4,"marks":[16,20],"descriptor":"Clear and explained. A clear response to task and text; effective use of references; clear explanation of the writer''s methods and their effects with relevant terminology; clear understanding of context linked to the text."},{"level":3,"marks":[11,15],"descriptor":"Some explanation. Some explained response; references used to support points; some identification and explanation of methods; some awareness of context."},{"level":2,"marks":[6,10],"descriptor":"Supported and relevant comments. Relevant comments backed by some reference; awareness of the writer making choices; some awareness of context."},{"level":1,"marks":[1,5],"descriptor":"Simple, explicit comments. Simple comments with little reference to the text; little awareness of methods or context."}],"indicative":["Ozymandias: power is temporary; nature and time destroy human pride","The ''shattered visage'' and ''sneer of cold command'' show arrogance and cruelty","Irony of the inscription against ''Nothing beside remains''","Form: a sonnet with an irregular rhyme scheme, perhaps reflecting broken power; framed narrative distances the king","Good comparisons: My Last Duchess (controlling power of a man over a woman), London (power of institutions over people), Extract from The Prelude (power of nature), Storm on the Island","Comparison should cover ideas and methods (language, structure, form) for both poems","Context: Shelley''s Romantic and revolutionary views, his hostility to tyranny","A strong answer compares throughout rather than writing about each poem separately"]}'::jsonb, '{"AO1":12,"AO2":12,"AO3":6}'::jsonb, 0 from q;

