insert into public.fm_mark_schemes (question_id, marking_style, scheme, ao_marks, spag_marks)
select id, 'levels', '{"levels":[{"level":4,"marks":[7,8],"descriptor":"Perceptive, detailed analysis of the writer''s methods with precise references and apt terminology; ideas linked to the writer''s purpose or context where relevant."},{"level":3,"marks":[5,6],"descriptor":"Clear explanation of how methods create meaning, with well-chosen references and relevant terminology."},{"level":2,"marks":[3,4],"descriptor":"Some explanation of meaning with some reference to the text; methods identified but only partly explained."},{"level":1,"marks":[1,2],"descriptor":"Simple comments about the character or idea, mostly retelling, with little or no analysis."}],"indicative":["The question shows confusion and doubt: he can''t trust his own senses","The dagger may be a hallucination caused by guilt, or a supernatural temptation","''The handle toward my hand'' suggests the murder is being offered to him; he is being drawn towards it","The imperative ''Come, let me clutch thee'' shows a desperate, grasping ambition","A soliloquy lets the audience see his private fears, building tension before the murder","Links to the supernatural and to the witches'' influence"]}'::jsonb, '{"AO1":3,"AO2":5}'::jsonb, 0 from q;

