select id, 'levels', '{"levels":[{"level":4,"marks":[7,8],"descriptor":"Perceptive, detailed analysis of the writer''s methods with precise references and apt terminology; ideas linked to the writer''s purpose or context where relevant."},{"level":3,"marks":[5,6],"descriptor":"Clear explanation of how methods create meaning, with well-chosen references and relevant terminology."},{"level":2,"marks":[3,4],"descriptor":"Some explanation of meaning with some reference to the text; methods identified but only partly explained."},{"level":1,"marks":[1,2],"descriptor":"Simple comments about the character or idea, mostly retelling, with little or no analysis."}],"indicative":["They are allegorical figures, not real children, representing society''s neglect","Descriptions such as ''wretched, abject, frightful, hideous, miserable'' shock the reader","The warning about the boy (Ignorance) and ''Doom'' shows Dickens believed ignorance was most dangerous","The Ghost throws Scrooge''s own words back at him (''Are there no prisons? Are there no workhouses?'')","Context: Dickens''s concern about child poverty, the ragged schools and the 1834 Poor Law","The scene is a turning point in Scrooge''s understanding of his responsibility"]}'::jsonb, '{"AO1":3,"AO2":3,"AO3":2}'::jsonb, 0 from q;

