insert into public.fm_mark_schemes (question_id, marking_style, scheme, ao_marks, spag_marks)
select id, 'levels', '{"levels":[{"level":4,"marks":[7,8],"descriptor":"Perceptive, detailed analysis of the writer''s methods with precise references and apt terminology; ideas linked to the writer''s purpose or context where relevant."},{"level":3,"marks":[5,6],"descriptor":"Clear explanation of how methods create meaning, with well-chosen references and relevant terminology."},{"level":2,"marks":[3,4],"descriptor":"Some explanation of meaning with some reference to the text; methods identified but only partly explained."},{"level":1,"marks":[1,2],"descriptor":"Simple comments about the character or idea, mostly retelling, with little or no analysis."}],"indicative":["The weather is the real enemy: ''the merciless iced east winds that knive us''","The repeated refrain ''But nothing happens'' shows boredom, waiting and futility","Half-rhymes and long, slow lines create unease and a sense of things not resolving","Present tense and collective ''we'' make the suffering shared and immediate","Soldiers'' minds drift home, but ''on us the doors are closed'', showing despair","Context: Owen''s own experience in the trenches in winter 1917; protest against the glorification of war"]}'::jsonb, '{"AO1":3,"AO2":3,"AO3":2}'::jsonb, 0 from q;

